html:
{% set tasks = frappe.get_all('Task', filters={'project': doc.project}, fields=['name','subject','status','ep_action_category','exp_start_date','exp_end_date','_assign'], order_by='ep_sort_order asc, creation asc') %}
<h1 style="font-size:20px;font-weight:700;margin-bottom:16px;">Action Plan — {{ doc.project }}</h1>
{% set cats = namespace(last='') %}
{% for t in tasks %}
  {% if t.ep_action_category != cats.last %}
    {% if cats.last != '' %}</tbody></table>{% endif %}
    <h3 style="font-size:13px;text-transform:uppercase;letter-spacing:.1em;color:#6b7280;margin:16px 0 6px;">{{ t.ep_action_category or 'Uncategorised' }}</h3>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr><th style="text-align:left;padding:5px 8px;border-bottom:1px solid #e5e7eb;">Task</th><th style="text-align:left;padding:5px 8px;border-bottom:1px solid #e5e7eb;">Status</th><th style="text-align:left;padding:5px 8px;border-bottom:1px solid #e5e7eb;">Assigned</th><th style="text-align:left;padding:5px 8px;border-bottom:1px solid #e5e7eb;">Due</th></tr></thead><tbody>
    {% set cats.last = t.ep_action_category %}
  {% endif %}
  <tr>
    <td style="padding:5px 8px;border-bottom:1px solid #f3f4f6;">{{ t.subject }}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f3f4f6;">{{ t.status }}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f3f4f6;">{% set _assigned = frappe.parse_json(t._assign or '[]') %}{{ _assigned[0] if _assigned else '—' }}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f3f4f6;">{{ t.exp_end_date or '—' }}</td>
  </tr>
{% endfor %}
{% if tasks %}</tbody></table>{% endif %}
